"""Absence notices for parents, built from marks."""

from typing import List
from rosterkit.models import Student, Mark
from rosterkit.attendance import days_missed
from datetime import date

def _check_own(student: Student, marks: List[Mark]) -> None:
    """Refuse marks recorded for anyone but this student."""
    found = {mark.student_id for mark in marks}
    others = found - {student.student_id}
    if others:
        raise ValueError(
            f"marks for other students: {sorted(others)}"
        )

def _format_day(when: date) -> str:
    """Spelled out, like September 1, 2026."""
    return f"{when:%B} {when.day}, {when.year}"

def _notice_text(student: Student, days: List[date]) -> str:
    """Wording of the notice for one student's absences."""
    listed = "; ".join(_format_day(when) for when in days)
    noun = "day" if len(days) == 1 else "days"
    name = f"{student.first_name} {student.last_name}"
    text = f"{name} was marked absent on {len(days)} {noun}"
    return f"{text}: {listed}."

# ---
def make_notice(student: Student, marks: List[Mark]) -> str:
    """Notice listing the days a student was absent."""
    _check_own(student, marks)
    days = days_missed(marks)
    if not days:
        raise ValueError("no absences to report")
    return _notice_text(student, days)
